<script setup>
import {ref,onMounted} from 'vue';
import {api} from '../api';
const props=defineProps({student:{type:Boolean,default:false},studentId:{type:String,default:''}});
const result=ref({items:[],total:0});const page=ref(0);const error=ref('');const loading=ref(false);
const labels={OPENING:'期初余额',COURSE:'课程获得',MANUAL:'人工调整',REDEMPTION:'奖品兑换',IMPORT_REVERSAL:'导入冲正',REFUND:'兑换退款',TRANSFER_IN:'转入',TRANSFER_OUT:'转出'};
async function load(step=0){if(loading.value)return;loading.value=true;error.value='';const target=Math.max(0,page.value+step);try{result.value=await api((props.student?'/public/rankings/student-ledger':`/rankings/admin/operations/students/${encodeURIComponent(props.studentId)}/ledger`)+`?page=${target}`);page.value=target;}catch(e){error.value=e.message;}finally{loading.value=false;}}
onMounted(()=>load());
</script>
<template><section class="ledger-panel"><header><h3>积分明细</h3><button type="button" @click="load()" :disabled="loading">刷新</button></header><p v-if="error" role="alert">{{error}}</p><div class="ledger-scroll"><table><thead><tr><th>时间 / 来源</th><th>变动</th><th>变动前 → 后</th><th>说明</th></tr></thead><tbody><tr v-for="r in result.items" :key="r.id"><td>{{new Date(r.created_at).toLocaleString('zh-CN')}}<small>{{labels[r.event_type]||r.event_type}}</small></td><td :class="r.delta<0?'negative':'positive'">{{r.delta>0?'+':''}}{{r.delta}}</td><td>{{r.balance_before}} → {{r.balance_after}}</td><td>{{r.reason}}</td></tr><tr v-if="!result.items.length"><td colspan="4">暂无积分变动</td></tr></tbody></table></div><footer><button @click="load(-1)" :disabled="loading||page===0">上一页</button><span>第 {{page+1}} 页 · {{result.total}} 条</span><button @click="load(1)" :disabled="loading||(page+1)*30>=result.total">下一页</button></footer></section></template>
<style scoped>.ledger-panel{min-width:0;max-width:100%;padding:18px;border:1px solid currentColor;border-radius:12px;margin:16px 0;font-size:14px}.ledger-panel header,.ledger-panel footer{display:flex;align-items:center;justify-content:space-between;gap:12px}.ledger-panel h3{margin:0}.ledger-scroll{overflow:auto}.ledger-panel table{width:100%;border-collapse:collapse;margin:16px 0}.ledger-panel th,.ledger-panel td{padding:10px 8px;border-bottom:1px solid #80808040;text-align:left;white-space:normal;min-width:80px}.ledger-panel small{display:block;opacity:.7}.positive{color:#219a78}.negative{color:#db6363}.ledger-panel button{padding:7px 12px;border:1px solid currentColor;border-radius:6px;background:transparent;color:inherit;cursor:pointer}.ledger-panel button:disabled{opacity:.4;cursor:default}</style>
